/**
 * @file macho.c
 * @brief 32-bit Mach-O loader (MH_EXECUTE, ARMv6 / ARMv7) for PlayStation Vita.
 * @details
 * 1. __TEXT is assembled in temporary memory and copied to an RX block via kubridge;
 *    __DATA is mapped to a RW block right after it, at the fixed address vmaddr + MACHO_SLIDE
 *    (the code is PIC: TEXT and DATA must keep their distance).
 * 2. rebase.bin (generated by tools/macho_prep.py) lists every absolute pointer (TEXT and DATA,
 *    including local __nl_symbol_ptr slots and __mod_init_func) that gets += MACHO_SLIDE.
 * 3. Imports: resolves dynamic imports intercepting calls to iOS / Darwin / UIKit libraries.
 *    Any unresolved symbol routes to an automatic logging thunk that returns 0.
 */
#include <kubridge.h>
#include <psp2/kernel/sysmem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "imports.h"
#include "log.h"
#include "macho.h"

#define LC_SEGMENT 0x1
#define LC_SYMTAB 0x2
#define LC_DYSYMTAB 0xB
#define LC_ENCRYPTION_INFO 0x21

#define S_ZEROFILL 0x1
#define S_NON_LAZY_SYMBOL_POINTERS 0x6
#define S_LAZY_SYMBOL_POINTERS 0x7

#define INDIRECT_SYMBOL_LOCAL 0x80000000u
#define INDIRECT_SYMBOL_ABS 0x40000000u

#define N_STAB 0xE0
#define N_TYPE 0x0E
#define N_SECT 0x0E
#define N_ARM_THUMB_DEF 0x0008

#ifndef SCE_KERNEL_MEMBLOCK_TYPE_USER_RX
#define SCE_KERNEL_MEMBLOCK_TYPE_USER_RX 0x0C20D050
#endif

#define ALIGN(x, a) (((x) + (a)-1) & ~((a)-1))
#define THUNK_ARENA_SIZE 0x20000

typedef struct {
    char segname[16];
    uint32_t vmaddr, vmsize, fileoff, filesize, maxprot, initprot, nsects, flags;
} segment_command;

typedef struct {
    char sectname[16], segname[16];
    uint32_t addr, size, offset, align, reloff, nreloc, flags, reserved1, reserved2;
} section;

typedef struct {
    uint32_t n_strx;
    uint8_t n_type, n_sect;
    uint16_t n_desc;
    uint32_t n_value;
} nlist;

typedef struct {
    uint32_t ilocalsym, nlocalsym, iextdefsym, nextdefsym, iundefsym, nundefsym, tocoff, ntoc,
        modtaboff, nmodtab, extrefsymoff, nextrefsyms, indirectsymoff, nindirectsyms, extreloff,
        nextrel, locreloff, nlocrel;
} dysymtab_command;

static uint8_t *file; // whole Mach-O slice, kept alive for the symbol table (macho_sym)
static nlist *symtab;
static uint32_t nsyms;
static const char *strtab;
static uint32_t text_vm, text_size, data_vm, data_size;
static uint8_t *text_buf;   // editable __TEXT copy, moved to the RX block at the end
static uintptr_t text_real; // runtime address of __TEXT
static uint32_t mod_init_addr, mod_init_count;

// Sorted (name, runtime_addr) view of defined symbols for O(log n) lookup.
typedef struct {
    const char *name;
    uintptr_t addr;
} sym_ent;
static sym_ent *sym_sorted;
static uint32_t sym_sorted_count;

static int sym_cmp(const void *a, const void *b) {
    return strcmp(((const sym_ent *)a)->name, ((const sym_ent *)b)->name);
}

static void build_sym_sorted(void) {
    if (sym_sorted || !symtab || !strtab)
        return;
    sym_sorted = calloc(nsyms ? nsyms : 1, sizeof(*sym_sorted));
    if (!sym_sorted)
        return;
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *s = &symtab[i];
        if (s->n_type & N_STAB || (s->n_type & N_TYPE) != N_SECT)
            continue;
        uintptr_t a = MACHO_SLIDE + s->n_value;
        if (s->n_desc & N_ARM_THUMB_DEF)
            a |= 1;
        sym_sorted[sym_sorted_count].name = strtab + s->n_strx;
        sym_sorted[sym_sorted_count].addr = a;
        sym_sorted_count++;
    }
    qsort(sym_sorted, sym_sorted_count, sizeof(*sym_sorted), sym_cmp);
}

static uint32_t *thunk_head, *thunk_end;
static const char **unimpl_names;
static int unimpl_count;

extern void ml_unimpl_entry(void);
extern void ml_align_call(void);

void ml_unimpl_log(int idx) {
    static uint8_t seen[4096];
    if (idx < (int)sizeof(seen) && seen[idx] < 3) {
        seen[idx]++;
        l_warn("unimpl import: %s%s", unimpl_names[idx], seen[idx] == 3 ? " (silenced)" : "");
    }
}

static uintptr_t make_thunk(uint32_t ip_value, void *jump) {
    if (thunk_head + 4 > thunk_end)
        fatal_error("Thunk arena exhausted");
    uint32_t code[4] = {
        0xE59FC000, // ldr ip, [pc, #0]
        0xE59FF000, // ldr pc, [pc, #0]
        ip_value,
        (uint32_t)jump,
    };
    uintptr_t addr = (uintptr_t)thunk_head;
    kuKernelCpuUnrestrictedMemcpy(thunk_head, code, sizeof(code));
    kuKernelFlushCaches(thunk_head, sizeof(code));
    thunk_head += 4;
    return addr;
}

static uintptr_t make_unimpl_thunk(const char *name) {
    unimpl_names = realloc(unimpl_names, (unimpl_count + 1) * sizeof(char *));
    unimpl_names[unimpl_count] = name;
    return make_thunk(unimpl_count++, ml_unimpl_entry);
}

static uintptr_t make_unimpl_data(const char *name) {
    static struct {
        const char *name;
        uintptr_t addr;
    } blocks[512];
    static int nblocks;
    for (int i = 0; i < nblocks; i++)
        if (!strcmp(blocks[i].name, name))
            return blocks[i].addr;
    void *b = calloc(1, 256);
    if (nblocks < 512)
        blocks[nblocks++] = (typeof(blocks[0])){name, (uintptr_t)b};
    return (uintptr_t)b;
}

uintptr_t macho_sym(const char *name) {
    build_sym_sorted();
    if (!sym_sorted)
        return 0;
    uint32_t lo = 0, hi = sym_sorted_count;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        int c = strcmp(sym_sorted[mid].name, name);
        if (c == 0)
            return sym_sorted[mid].addr;
        if (c < 0)
            lo = mid + 1;
        else
            hi = mid;
    }
    return 0;
}

// Resolves a dynamic symbol name to a runtime address: loader import table first,
// then symbols defined inside the guest binary (self-referencing function pointers).
uintptr_t macho_resolve(const char *name) {
    const import_entry *imp = imports_lookup(name);
    if (imp)
        return imp->data ? imp->addr : (uintptr_t)make_thunk(imp->addr, ml_align_call);
    return macho_sym(name);
}

static uint32_t *word_ptr(uint32_t vmaddr) {
    if (vmaddr >= text_vm && vmaddr + 4 <= text_vm + text_size)
        return (uint32_t *)(text_buf + (vmaddr - text_vm));
    if (vmaddr >= data_vm && vmaddr + 4 <= data_vm + data_size)
        return (uint32_t *)(data_vm + MACHO_SLIDE + (vmaddr - data_vm));
    return NULL;
}

// Import slot value: our implementation (functions enter through ml_align_call), else a
// coalesced/weak symbol defined in the guest itself, else a logging stub (code) or a zero block (data).
static uintptr_t resolve(const char *name, int is_lazy) {
    const import_entry *e = imports_lookup(name);
    if (e)
        return e->data ? e->addr : make_thunk(e->addr, ml_align_call);
    uintptr_t s = macho_sym(name);
    if (s)
        return s;
    return is_lazy ? make_unimpl_thunk(name) : make_unimpl_data(name);
}

static int alloc_block(const char *name, int type, uintptr_t addr, uint32_t size) {
    SceKernelAllocMemBlockKernelOpt opt;
    memset(&opt, 0, sizeof(opt));
    opt.size = sizeof(opt);
    opt.attr = 0x1;
    opt.field_C = addr;
    SceUID id = kuKernelAllocMemBlock(name, type, size, &opt);
    if (id < 0)
        return id;
    void *base;
    sceKernelGetMemBlockBase(id, &base);
    if ((uintptr_t)base != addr)
        fatal_error("%s mapped at %p instead of 0x%08X", name, base, (unsigned)addr);
    return 0;
}

int macho_load(const char *bin_path, const char *rebase_path) {
    l_info("Loading Mach-O executable: %s", bin_path);
    FILE *f = fopen(bin_path, "rb");
    if (!f)
        fatal_error("Failed to open %s", bin_path);
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *raw = malloc(fsize);
    if (!raw)
        fatal_error("Insufficient memory to load %s", bin_path);
    fread(raw, 1, fsize, f);
    fclose(f);

    // FAT universal binary (big-endian 0xCAFEBABE): prefer armv7, else armv6.
    file = raw;
    if (fsize >= 8 && !memcmp(raw, "\xca\xfe\xba\xbe", 4)) {
        uint32_t nfat = __builtin_bswap32(((uint32_t *)raw)[1]), best = 0;
        for (uint32_t i = 0; i < nfat; i++) {
            const uint32_t *a = (const uint32_t *)(raw + 8 + i * 20);
            uint32_t cpu = __builtin_bswap32(a[0]), sub = __builtin_bswap32(a[1]);
            if (cpu == 12 && (sub == 9 || sub == 11 || (sub == 6 && !best)))
                best = __builtin_bswap32(a[2]);
        }
        if (!best)
            fatal_error("%s: FAT binary without an ARM slice", bin_path);
        file = raw + best;
        l_info("FAT binary: using slice at offset 0x%X", (unsigned)best);
    }

    uint32_t *hdr = (uint32_t *)file;
    if (hdr[0] != 0xFEEDFACE || hdr[1] != 12 || hdr[3] != 2)
        fatal_error("%s is not a 32-bit ARM MH_EXECUTE (magic 0x%08X)", bin_path, (unsigned)hdr[0]);

    segment_command *text_seg = NULL, *data_seg = NULL;
    dysymtab_command *dysym = NULL;
    section *sects[64];
    int nsect = 0;
    uint8_t *lc = file + 28;
    for (uint32_t i = 0; i < hdr[4]; i++) {
        uint32_t cmd = ((uint32_t *)lc)[0], size = ((uint32_t *)lc)[1];
        if (cmd == LC_SEGMENT) {
            segment_command *seg = (segment_command *)(lc + 8);
            if (!strncmp(seg->segname, "__TEXT", 16))
                text_seg = seg;
            else if (!strncmp(seg->segname, "__DATA", 16))
                data_seg = seg;
            section *s = (section *)(seg + 1);
            for (uint32_t j = 0; j < seg->nsects && nsect < 64; j++)
                sects[nsect++] = &s[j];
        } else if (cmd == LC_SYMTAB) {
            uint32_t *st = (uint32_t *)(lc + 8);
            symtab = (nlist *)(file + st[0]);
            nsyms = st[1];
            strtab = (const char *)(file + st[2]);
        } else if (cmd == LC_DYSYMTAB) {
            dysym = (dysymtab_command *)(lc + 8);
        } else if (cmd == LC_ENCRYPTION_INFO && ((uint32_t *)lc)[4] != 0) {
            fatal_error("Executable is still FairPlay encrypted (cryptid=1): a decrypted one is required");
        }
        lc += size;
    }
    if (!text_seg || !data_seg || !symtab || !dysym)
        fatal_error("Incomplete Mach-O: missing __TEXT/__DATA/LC_SYMTAB/LC_DYSYMTAB");

    text_vm = text_seg->vmaddr;
    text_size = text_seg->vmsize;
    data_vm = data_seg->vmaddr;
    data_size = data_seg->vmsize;
    if (data_vm != text_vm + text_size)
        fatal_error("__DATA does not follow __TEXT");
    text_real = text_vm + MACHO_SLIDE;
    l_info("Mach-O: TEXT 0x%08X+0x%X DATA 0x%08X+0x%X -> real 0x%08X", (unsigned)text_vm,
           (unsigned)text_size, (unsigned)data_vm, (unsigned)data_size, (unsigned)text_real);

    if (alloc_block("ml_thunks", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, text_real - THUNK_ARENA_SIZE,
                    THUNK_ARENA_SIZE) < 0 ||
        alloc_block("ml_text", SCE_KERNEL_MEMBLOCK_TYPE_USER_RX, text_real, ALIGN(text_size, 0x1000)) < 0 ||
        alloc_block("ml_data", SCE_KERNEL_MEMBLOCK_TYPE_USER_RW, data_vm + MACHO_SLIDE, ALIGN(data_size, 0x1000)) < 0)
        fatal_error("kuKernelAllocMemBlock failed: is kubridge.skprx in ur0:tai/config.txt?");
    thunk_head = (uint32_t *)(text_real - THUNK_ARENA_SIZE);
    thunk_end = (uint32_t *)text_real;

    text_buf = calloc(1, text_size);
    memcpy(text_buf, file + text_seg->fileoff, text_seg->filesize);
    uint8_t *data_real = (uint8_t *)(data_vm + MACHO_SLIDE);
    memset(data_real, 0, ALIGN(data_size, 0x1000));
    memcpy(data_real, file + data_seg->fileoff, data_seg->filesize);

    // Precomputed rebases (they already cover local __nl_symbol_ptr slots and __mod_init_func).
    f = fopen(rebase_path, "rb");
    if (!f)
        fatal_error("Missing %s (generate it with tools/macho_prep.py)", rebase_path);
    uint32_t rh[2];
    fread(rh, 4, 2, f);
    if (rh[0] != 0x31534252) // 'RBS1'
        fatal_error("%s is not a valid rebase.bin", rebase_path);
    uint32_t *rebase = malloc(rh[1] * 4);
    fread(rebase, 4, rh[1], f);
    fclose(f);
    for (uint32_t i = 0; i < rh[1]; i++) {
        uint32_t *w = word_ptr(rebase[i]);
        if (!w)
            fatal_error("rebase outside the image: 0x%08X", (unsigned)rebase[i]);
        *w += MACHO_SLIDE;
    }
    free(rebase);
    l_info("rebase: %u words", (unsigned)rh[1]);

    // Imports through the indirect symbol table.
    uint32_t *indirect = (uint32_t *)(file + dysym->indirectsymoff);
    int n_imports = 0;
    for (int i = 0; i < nsect; i++) {
        section *s = sects[i];
        uint32_t type = s->flags & 0xFF;
        if (!strncmp(s->sectname, "__mod_init_func", 16)) {
            mod_init_addr = s->addr;
            mod_init_count = s->size / 4;
        }
        if (type != S_LAZY_SYMBOL_POINTERS && type != S_NON_LAZY_SYMBOL_POINTERS)
            continue;
        for (uint32_t j = 0; j < s->size / 4; j++) {
            uint32_t idx = indirect[s->reserved1 + j];
            if (idx & (INDIRECT_SYMBOL_LOCAL | INDIRECT_SYMBOL_ABS))
                continue; // locals were already covered by rebase.bin
            *word_ptr(s->addr + j * 4) =
                resolve(strtab + symtab[idx].n_strx, type == S_LAZY_SYMBOL_POINTERS);
            n_imports++;
        }
    }
    // External relocations (GENERIC_RELOC_VANILLA): slot = symbol + addend already stored in the slot
    // (e.g. vptr = vtable for __class_type_info + 8).
    uint32_t *rel = (uint32_t *)(file + dysym->extreloff);
    for (uint32_t i = 0; i < dysym->nextrel; i++) {
        uint32_t addr = rel[i * 2], info = rel[i * 2 + 1];
        uint32_t *w = word_ptr(addr);
        if (!w || ((info >> 28) & 0xF) != 0 || ((info >> 25) & 3) != 2)
            fatal_error("unsupported external reloc at 0x%08X (info 0x%08X)", (unsigned)addr, (unsigned)info);
        *w += resolve(strtab + symtab[info & 0xFFFFFF].n_strx, 0);
        n_imports++;
    }
    l_info("imports: %d slots, %d unimplemented", n_imports, unimpl_count);

    kuKernelCpuUnrestrictedMemcpy((void *)text_real, text_buf, text_size);
    kuKernelFlushCaches((void *)text_real, text_size);
    free(text_buf);
    text_buf = NULL;
    return 0;
}

// No per-constructor log: each flushed line costs ~9 ms on ux0 (366 constructors = 3 s of boot),
// and a crash dump already gives the exact PC/LR.
void macho_run_inits(void) {
    l_info("running %u global constructors...", (unsigned)mod_init_count);
    for (uint32_t i = 0; i < mod_init_count; i++) {
        uintptr_t fn = ((uint32_t *)(mod_init_addr + MACHO_SLIDE))[i]; // already slid by rebase.bin
        call_guest((void *)fn, 0, 0, 0, 0);
    }
    l_info("global constructors: %u done", (unsigned)mod_init_count);
}

static nlist *find_sym(const char *name) {
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *s = &symtab[i];
        if (!(s->n_type & N_STAB) && (s->n_type & N_TYPE) == N_SECT && !strcmp(strtab + s->n_strx, name))
            return s;
    }
    return NULL;
}

void macho_hook(const char *name, void *dst) {
    nlist *s = find_sym(name);
    if (!s)
        fatal_error("hook: %s does not exist", name);
    // Size = distance to the next code symbol in the same section.
    uint32_t next = 0xFFFFFFFF;
    for (uint32_t i = 0; i < nsyms; i++) {
        nlist *o = &symtab[i];
        if (!(o->n_type & N_STAB) && (o->n_type & N_TYPE) == N_SECT && o->n_sect == s->n_sect &&
            o->n_value > s->n_value && o->n_value < next)
            next = o->n_value;
    }
    uintptr_t addr = s->n_value + MACHO_SLIDE;
    uint32_t patch[2];
    uint32_t need;
    if (s->n_desc & N_ARM_THUMB_DEF) {
        uint16_t nop = 0xBF00;
        need = 8 + (addr & 2);
        if (next - s->n_value < need)
            fatal_error("hook: %s is %u bytes, jump does not fit", name, (unsigned)(next - s->n_value));
        if (addr & 2) {
            kuKernelCpuUnrestrictedMemcpy((void *)addr, &nop, 2);
            addr += 2;
        }
        patch[0] = 0xF000F8DF; // ldr.w pc, [pc]
    } else {
        need = 8;
        if (next - s->n_value < need)
            fatal_error("hook: %s is %u bytes, jump does not fit", name, (unsigned)(next - s->n_value));
        patch[0] = 0xE51FF004; // ldr pc, [pc, #-4]
    }
    patch[1] = make_thunk((uint32_t)dst, ml_align_call); // enter with an aligned stack
    kuKernelCpuUnrestrictedMemcpy((void *)addr, patch, sizeof(patch));
    kuKernelFlushCaches((void *)(addr & ~3), 16);
}
